<script setup lang="ts">import {computed} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {projects} from '../data/site';import {ArrowLeft,ArrowUpRight} from 'lucide-vue-next';const route=useRoute();const project=computed(()=>projects.find(p=>p.slug===route.params.slug));</script>
<template><div class="inner-page" v-if="project"><RouterLink to="/projects" class="back-link"><ArrowLeft :size="15"/> 返回项目列表</RouterLink><div class="page-hero"><div class="eyebrow">{{project.category}} / {{project.number}}</div><h1>{{project.title}}<span class="gradient-text">.</span></h1><p>{{project.desc}}</p></div><div class="detail-panel"><span class="project-status">{{project.status}}</span><h2>项目说明</h2><p>这是一个持续演进中的项目方向。当前页面作为项目档案入口，后续可以补充真实截图、技术架构、功能清单、阶段成果与在线演示。</p><div class="focus-chips"><span v-for="t in project.tags" :key="t">{{t}}</span></div><a href="https://github.com/zh370565973" target="_blank" class="text-link">查看 GitHub <ArrowUpRight :size="16"/></a></div></div><div v-else class="inner-page"><h1>未找到这个项目</h1><RouterLink to="/projects">返回项目列表</RouterLink></div></template>